No search input in the working dir (config dir only), so framework-agnostic version:

```js
const input = document.querySelector('#search');
let timer, controller;

input.addEventListener('input', () => {
  clearTimeout(timer);
  timer = setTimeout(async () => {
    controller?.abort(); // cancel in-flight request so a slow old response can't overwrite a newer one
    controller = new AbortController();
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(input.value)}`, { signal: controller.signal });
      render(await res.json());
    } catch (e) {
      if (e.name !== 'AbortError') throw e;
    }
  }, 300);
});
```

React equivalent:

```jsx
useEffect(() => {
  const controller = new AbortController();
  const timer = setTimeout(() => {
    fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal: controller.signal })
      .then(r => r.json())
      .then(setResults)
      .catch(e => { if (e.name !== 'AbortError') throw e; });
  }, 300);
  return () => { clearTimeout(timer); controller.abort(); };
}, [query]);
```

